## Bibliography

If you make use of Mallob in an academic / scientific setting or in a competitive event, please cite the most relevant among the following publications (all Open Access).

#### Focus on SAT Solving (JAIR'24)

@article{schreiber2024mallobsat,  title={{MallobSat}: Scalable {SAT} Solving by Clause Sharing},  author={Schreiber, Dominik and Sanders, Peter},  journal={Journal of Artificial Intelligence Research (JAIR)},  year={2024},  volume={80},  pages={1437--1495},  doi={10.1613/jair.1.15827}, }

#### Focus on job scheduling (Euro-Par'22)

@inproceedings{sanders2022decentralized,  title={Decentralized Online Scheduling of Malleable {NP}-hard Jobs},  author={Sanders, Peter and Schreiber, Dominik},  booktitle={International European Conference on Parallel and Distributed Computing},  pages={119--135},  year={2022},  organization={Springer},  doi={10.1007/978-3-031-12597-3_8} }

#### Monolithic proofs of unsatisfiability (JAR'25)

@article{michaelson2025producing,  author={Michaelson, Dawn and Schreiber, Dominik and Heule, Marijn J. H. and Kiesl-Reiter, Benjamin and Whalen, Michael W.},  title={Producing Proofs of Unsatisfiability with Distributed Clause-Sharing {SAT} Solvers},  journal={Journal of Automated Reasoning (JAR)},  year={2025},  organization={Springer},  volume={69},  doi={10.1007/s10817-025-09725-w}, }

#### Real-time proof checking (SAT'24)

@inproceedings{schreiber2024trusted,  title={Trusted Scalable {SAT} Solving with on-the-fly {LRAT} Checking},  author={Schreiber, Dominik},  booktitle={Theory and Applications of Satisfiability Testing (SAT)},  year={2024},  pages={25:1--25:19},  organization={Schloss Dagstuhl -- Leibniz-Zentrum für Informatik},  doi={10.4230/LIPIcs.SAT.2024.25}, }

#### MaxSAT Solving (SoCS'25)

@inproceedings{schreiber2025from,  author={Schreiber, Dominik and Jabs, Christoph and Berg, Jeremias},  title={From Scalable {SAT} to {MaxSAT}: Massively parallel Solution Improving Search},  booktitle={Symposium on Combinatorial Search (SoCS)},  year={2025},  doi={10.1609/socs.v18i1.35984},  volume={18},  number={1},  pages={127--135}, }

#### Most recent SAT Competition solver description (TR)

@inproceedings{schreiber2024mallob,  title={{MallobSat} and {MallobSat-ImpCheck} in the {SAT} Competition 2024},  author={Schreiber, Dominik},  booktitle={SAT Competition 2024: Solver, Benchmark and Proof Checker Descriptions},  year={2024},  pages={21--22},  url={http://hdl.handle.net/10138/584822}, }

#### Distributed Incremental SAT Solving (TR)

@misc{schreiber2025distributed,  title={Distributed Incremental {SAT} Solving with {Mallob}: Report and Case Study with Hierarchical Planning},  author={Dominik Schreiber},  year={2025},  eprint={2505.18836},  archivePrefix={arXiv},  primaryClass={cs.DC},  url={https://arxiv.org/abs/2505.18836}, }

